package com.trendinvestorr.data.model;

import com.trendinvestorr.core.constants.SignalSource;
import com.trendinvestorr.core.constants.SignalStatus;
import com.trendinvestorr.core.constants.SignalStrength;
import com.trendinvestorr.core.constants.SignalType;
import com.trendinvestorr.core.constants.MarketConstants;

import java.time.Instant;
import java.util.Map;

/**
 * Trading signal generated by any scanner in the engine.
 * Port of {@code data.models.market_data.Signal}.
 *
 * <p>Mutable (uses {@code status}), so modelled as a class rather than a record.
 */
public class Signal {
    private final String symbol;
    private final String token;
    private final SignalType signalType;
    private final SignalStrength strength;
    private final double score;        // 0.0 - 1.0 composite score
    private final double price;        // price at signal generation
    private final SignalSource source;
    private final String sector;
    private final long volumeCurrent;
    private final long volumeAvg;
    private final double volumeRatio;
    private SignalStatus status;
    private final Instant createdAt;
    private final Map<String, Object> metadata;

    public Signal(String symbol, String token, SignalType signalType, SignalStrength strength,
                  double score, double price, SignalSource source, String sector,
                  long volumeCurrent, long volumeAvg, double volumeRatio,
                  SignalStatus status, Instant createdAt, Map<String, Object> metadata) {
        this.symbol = symbol;
        this.token = token;
        this.signalType = signalType;
        this.strength = strength;
        this.score = score;
        this.price = price;
        this.source = source == null ? SignalSource.VOLUME_SPIKE : source;
        this.sector = sector == null ? "" : sector;
        this.volumeCurrent = volumeCurrent;
        this.volumeAvg = volumeAvg;
        this.volumeRatio = volumeRatio;
        this.status = status == null ? SignalStatus.PENDING : status;
        this.createdAt = createdAt == null ? Instant.now() : createdAt;
        this.metadata = metadata == null ? Map.of() : metadata;
    }

    public Signal(String symbol, String token, SignalType signalType, SignalStrength strength,
                  double score, double price, SignalSource source,
                  double volumeRatio, Map<String, Object> metadata) {
        this(symbol, token, signalType, strength, score, price, source, "",
             0L, 0L, volumeRatio, SignalStatus.PENDING,
             Instant.now().atZone(MarketConstants.IST).toInstant(), metadata);
    }

    public String symbol() { return symbol; }
    public String token() { return token; }
    public SignalType signalType() { return signalType; }
    public SignalStrength strength() { return strength; }
    public double score() { return score; }
    public double price() { return price; }
    public SignalSource source() { return source; }
    public String sector() { return sector; }
    public long volumeCurrent() { return volumeCurrent; }
    public long volumeAvg() { return volumeAvg; }
    public double volumeRatio() { return volumeRatio; }
    public SignalStatus status() { return status; }
    public Instant createdAt() { return createdAt; }
    public Map<String, Object> metadata() { return metadata; }

    public void setStatus(SignalStatus status) { this.status = status; }

    /** Human-readable volume spike multiplier, e.g. {@code "3.4x"}. */
    public String volumeSpikeX() {
        return String.format("%.1fx", volumeRatio);
    }
}
